་ོྖ཰༅ལཅཞྛཡཎ࿘࿸༝ཧ࿥ཾྯལ༳ཝ༵༳࿍༇༬ཆ༟༣ྯྦྷ࿑࿖ྀ࿟࿙ྷༀ࿅ཪ཰࿀༁དམྒྷྒདྷཅཛྷྦཤ༽༭ཹྱ༟࿙༰ྲྃ࿰འྖ࿦࿎࿞࿸࿳ༀ࿅པ༉ན༌དཙྸ࿴ྪ࿵ཆ་ཡྶ࿶ྒྶ࿓཮།ྴ༣༛༎࿑࿌࿔࿱࿼࿩ཇྭྷཋཅཬ༎࿃༙࿡࿟༺བ࿖ེྫ࿶ྒ࿉༇྇ཨཔཧཥདག࿾྽ྭ༟༤࿕࿨࿼ྉ࿘࿶༆༿࿈༕࿮࿅ཛྷ྽་ཆཫྨ࿒ྠ༭ཾ༟༗༦ྚྶ࿐དྭ༟ཌ཰࿎༴༃༡࿟ྫྷ྽ཋ༑ཇ࿝ཎ཮྽༄ྌཤ཯༴ྟཨཷྎ࿦྄ངཤྐ࿎༷༅࿺།࿙ཤླྀཎ࿎ཱི࿽༃࿨ྡྷ༶཮࿆࿒ྌཤ࿍ྴ༅ྡཷ࿰༠༛ངྔད࿹༷༅࿺ཁཛ࿟ླྀ྾ྫྷྟཏྐྵཕ࿵༶࿐࿭ཛྷ༧࿡࿈࿼ཙ࿧࿓ྃ༕࿬པྉ࿎༞༤࿕ཌཡཷཀྵྦྷ࿠༽ྜྷཏ༑࿟༯ཱི༬༳ཬཫྒྑ༟྇ཆྊ༗ྰྚག࿰ྀ࿱࿼ྛྼ࿱ྷ༹༐༧༽࿃༝ྰ࿵ྻཫལ༳ཝཛྷ༳ྶ༇༅ཆྲྊཱྀྦྷ࿑࿫ཐ࿎ཌ༬ྷ࿎ཷེ༶࿠࿩ི࿆ླཕ༡༶྆࿗༧ཫ༃ག࿓ྟྡཷ࿭༃࿔ཚཹོ࿹༱ཉ༦࿫࿬༢ཅ࿠ྖམ࿀࿴དྷཇཁ࿷ཹ࿑ྕྒ༌༴ྈྂ༢࿎ྼ࿞࿤ཹཐ࿛࿳ཙལ࿵༴༒དྷ༾༮࿃༝࿦ཟཨ࿥ྞ༳࿠ཫ༃࿈ྴ཮བྵྎ࿡ོཚ༚ྐྖ྿ཷཥྌ༅༢ྡྷ༧࿛༅࿗༑࿏ཇྜ༭ཹ༵གྷཌྷ྽ྠ༭ཎཔ࿂ྐྵ༆༲࿴࿈༦ྣ࿓཈࿝࿺࿩ྡྷཊ༺྇࿩ྈྀྒྥ࿐࿭༾ྱླ࿍ྯ༬།ཷཧ༃ྍངཹ༆ྼ༤ཌྷ࿚ལ཰࿚࿶དལྸ࿡༡ཨ༔྇༳ཛྷཊ࿦ང࿄ྗ࿍ྠ࿖ཥ྄༲བྷༀ࿱༟࿸༉ཡཷེྡྙ࿇࿆ྎ࿦࿨࿝ཛྷ࿓࿭࿧࿤ཹ྄ྮྦྞྴྔླ྄དཅར༈࿸༅࿕ཡ༝ཷ༂࿤ྫྷ࿙༏ཱྀཎཧཽ༅༕ྱཝྰ༰༷༿ྺ཈࿴༃ྭ࿬࿭ྀ࿘࿙࿸ལ࿝ཏྰཀ࿤༺ཱི༏ཱྀ༡࿝ཛྷཞཛ༵རཋྻༀྨ࿧࿺࿗ཿ༈ྩ༗རྐྺམ࿼༸ཞ྅༐༰ྖྟཪ࿩༸ྗཛྷྤ࿌༰ྱ࿴ྍ༘ྤྞྯ࿖࿡ོྶེར࿱ཀྵྫྷ࿼༸༱༨࿲ཫ༺ལཉཨ༸ྗཆ༭ྔ࿑༵ྐྵ࿪ྯྤྞ࿼࿌࿡ད࿈༗༌༽༱࿓ལ༡ྯ༃༂ང྾༱ཿ࿰ཕ༎༯ྊ࿖ྱ࿑࿿࿍ྯ༳࿤཈࿴ྰྀ༲ཛ࿱࿛྿࿕༷࿨ལེ༶ྸ࿔ེ࿆༿དྷྼཛྷྊ྽࿤ངཤ࿈࿼཮།ཷྎཌྷྠྕ༑ཀ༎ཌༀྲ࿥ྸྪཀ࿤རྨ࿗ྉ༡ཕཊ༇ཛྕ࿎ལྻༀ࿃ྜ༴ཤྐྵ྄࿤ེར࿱ཱྀ༦࿐༸༱ྉ࿅ཬ༺ྈ༝ཱྀྏ།གྷ༅ཤ࿧༵࿦࿉༟༬།࿽ཱུྎ࿞ྩ༗ྐར࿳༅࿳࿲ྒྷ༺༂࿤ྫྷ཮ཻ༳ཟབཀྵྷ༳࿜༵ྐྵ༲࿾཈༰྘࿌ྃ༼༲ླརཫྠྤཔཕཷ༹࿲༵࿵཮࿽ྨདྷྍྥྣ࿗࿜ྱ༠༲࿺༬ཇྲ༦ཧ࿁༲࿭དྫྷༀལ཰༥༇࿽ླྀ࿑࿘཈༝ཧཟ༯༃ཱི༳ཛྷྱྃ࿶པ྇ཕ࿺ྐྵཧ྄࿒༕྄༎ྠ࿩྿࿮ྷྛ࿵ཎྖམ༝༗ཎ࿀༜༅ཹ࿑ྕ༦ངྯཱིཾྯ༢ཿ༼࿤࿫ྍ࿨༉཰ྲ࿥༝༼༼࿤࿵མ࿗ྐྵ࿏ྡྷྡ࿐ཤཛྷ࿜ྃའྵ༿ྦ༜࿴ཥོུ࿗༈࿞཰࿳༷ྡྷཔྛ༸ྫྷཾ࿜ཋྒ࿵࿏བ༩༚ཆཬ༠࿍࿓ྨ࿧ྊཹླྍའ࿰ད࿞ྈ༻༻࿎ྯ࿽࿗࿤༬ྶྤྐ࿖༏ཽ།༳༒ྊ࿆཮༰ག࿍ྱ࿴ྡ࿿࿟࿎ྛ࿭༱࿈པ཈༯཮ྎྯ༚྽ྖ࿰ཌྷ༝༽྾ཡ྽࿤ཱུྱྭ࿉ཱྀྡྦྷྭ࿢ༀ༑ྲ࿰࿁ནྶེལ࿔ླྀྺ࿗ཀ࿏༘࿄ྙྦ༅ག༩࿊ྭ༉ཁྦ࿷ྠ࿈࿱࿼ྜྷྪ࿡࿱࿉࿓༡ྎྖ࿥ཱ࿾༆༄ཋ༧ཻ཰ྴ༶༞འནཤ༙ྏ༹ྯ྾༐࿰༕࿑࿣࿴࿧༁གྷ༄࿚༁༢࿯༣ྕ࿬རྀ࿥ླྀྥྗ༽༎བྷ࿇ྟ༉ྲྞཀ࿎࿣༠཰ྫྷར࿻༟༞࿣ཎ࿧༆༢࿶ྀ࿆ྶ༈ཎ༖࿬྾༠༱࿶ཝ༅ཻཚྣ༶ྃ࿵࿞࿂࿘ྑ༗ག༫ྲྚྷ༧࿫ར࿖༄ྡྷཧ࿖ྗ࿦ྱྤཞཷོ༰࿃༭༳།༟ོ༦྇ླ༚༈࿎࿍༦࿫ཛྷ࿥༂཭ད༺ཇྟ࿽༕࿺྇ྐྵ༲ཀྵཀ࿋ཎཽྵ཰ྦྷཧཪཱིྣ༑ྸ༔ཪྦ༸࿁ཐྡྣ࿽འྛྦྷ࿮ཱི༱࿌࿢࿺བྷཹྠༀ࿢ཪ࿢࿘༛ྒྕྒ࿎༉ཽཋསྔཆ࿽ཱ࿤࿸ྶཷྐ࿖༏ཽ྿༳ཋྊྨ཮༰ག࿍ཱི࿴ྂ࿿࿔࿎ྛ࿭༱࿼པ࿯༯཰ྎ཭༚྽ླ࿰ྈ༝ཷ༡ཡ྽࿤༺ྱྀ࿉࿟ྡྦྷྭ࿢ྡ༑པ࿰ྺནྶེལྡྷླྀ྅࿗࿻࿏࿀࿽ྙ཯༅༊༩ྖྭ༉ཁྦྌྠས࿱༲ྜྷ࿏࿡࿱༩࿓༐ྎ࿇࿥ཱ࿾༆༵ཋྡཻྻྴྂ࿢འ༇ཤཱྏ࿴ྯྕ༐࿰ྫྷ࿑༔࿴ཊ༁࿈༄࿚༧༢༜༣ྕ࿬࿹ྀ࿥ཀྥཱུ༽༞བྷྚྟ༉།ྞྐ࿎࿯༠྿࿎རཏ༟ྪ࿣༭࿧༆༢࿶༈࿆ྶ༈།༖ྦྕ༠࿼࿶ྏ༅࿫ཚྣ༶༙ྃ࿞ྸ࿘ྴ༗ག༫ྲ༹ྷ༧࿫༞࿖࿣ྡྷཧ࿪ྗ࿦ྱ༭ཞཷྭ༰࿜༭࿿།྘ོ࿎ྜྷླ࿛༈ྫྷ࿍ཱྀ࿫༵ླྀ༂ྜྷད࿵ཇཱི࿽༕࿺྇ཟ༲ཀྵཀ࿪ཎ࿐ྯ཰࿔ཧཱི྆྘༑࿀༔ཪའ༸ྙཐཱིྣ࿽འྛ࿗࿮ཱི༱࿂࿢ྲ࿐ཹ༉ༀཕཪ࿽࿘ྚྒྕྛ࿎྄ཽ༷ས་ཆ࿽࿊࿤࿸ྶ༴ྐ࿖༏ཽས༳ྋྊཌྷ཮༓ཚ࿍཯࿴࿠࿿࿁࿎ྛ࿭༱࿈པྠ༯༪ྎྯ༚྽ྉ࿰࿯༝ྼ྾࿨྽࿤ྚྱ࿱࿉ྪྡཅྭ࿢ྂ༑ྴ࿰࿦ནྶེལྪླྀྺ࿗༑࿏༘࿄ྙ྆༅ན༩࿘ྭཫཎྦ༔ྠ࿶࿱ྶྜྷྪ࿡࿱࿉࿓࿝ྎི࿥ཱ࿾༆བྷཋ༶ཻཆྴ།༞འཷཤ࿀ྏ༿ྯ྾༐࿰࿝࿑ྥ࿴༧༁གྷ༄࿚༔༢ྨ༣ཫ࿬རྀ࿥༃ྥ༘༽༽བྷ࿖཮༉࿣ྞཐ࿎ཌྷ༠཰ྫྷརཏ༟ཕ࿣࿧࿧༆༢࿶༈࿆ྩ༈།༖ྦྕ༠࿼࿶ྂ༅࿫ཚྣ༶༙ྃ࿞ྸ࿘ྑ༗ག༫ྲ࿋ྷཫ࿫༐࿖࿣ྡྷཧྚྗ࿡ྱྤཞ༇ོ༰࿃༭༳།࿇࿍༦྇ླཅ༈ྖ࿍ཀྵ࿫༧ླྀ༂ནདྪཇཌྷ࿽༕࿺྇ྺ༲༦ཀ྄ཎ༔ྵྠ࿡༕࿀࿑༑ྃ༈྿࿓࿺༥࿢ཛླྀ༵࿞ྜྷྸ࿡ྼ༎ཾ྘༕འགྷ࿯࿙ྠ༭༰࿼࿰༃࿔࿒ྊཨྭ༟཰༷ཡཔ࿴ྼྖཛ༩ཋ࿡࿝ྡྷྜ༇༚ག࿎ྲྀྵༀ࿯ཆྯ༗༃ོཚ࿌ོ༮༉ལཌྷ࿝࿼࿩དྷ༵༆ྦྯ༒༈ྗ།྆༚ཬཫྐྵ࿈཭ྟཎ࿫འེ࿞࿉࿖ྐརྠༀ༻ཇ༱༨།࿻࿔࿆࿀༃࿲ཅབ྘࿻༮࿑࿝ྱ༱ྨ།༟༕༑྄ྶ࿰࿔༞༉ྠ཈࿎࿓ཋ࿲༾࿟཈༢ཧ࿚ྻག༻༳࿠༾࿻ངཉ཮࿧ྴཛཿའ།ྺ࿎ྼཌྠ࿳࿝࿺༦࿨࿶༆༿ཥ༕࿮࿲ཾ྆་ཝཬ࿯ཀྵྠ༭།ྴཹྒ࿋གྷབྷ࿕ྭ༟཰཰ྼ྽࿴࿏࿟࿺྆ཋ࿦ཡྚཡ࿈࿩༲༾ཥང༱࿃࿧པཱཛྶ࿐ཀྵ࿎ྖༀ࿕ཌྷ࿅ཞ༨࿅ཝ༺ྈྎ༗ྏཁ༉༅ཛ༾ཛྷ࿦࿉ྴ࿙༯࿓ྎ༿༼࿉࿖༼ྼ྿ༀལ࿎ཞ࿴ཅ༾༮ཙ༖࿡࿥ྙ࿲ཷ࿩༲࿑༳ྶ༟ཱིཎ༴࿗ཌྷ྆ཆ༑࿱རཌ༅཰ཇཞ༨།ྂ࿇࿆࿗༿དྷ࿅ྏ྆ྔཛྷ࿎ཝྕༀ࿃༯ཌ࿐།࿖࿑࿖࿋࿟཰༬྿ཅཞ༃ྡྷ༰ར༅࿗ྃ࿏ྦྷཛྷ༇࿭༧࿜࿻࿶ཉ࿯ུྎ࿘࿄࿞࿶ཤྍ࿹༻࿕ལ࿨ྲྺདྷ࿠༆྆ྯྣ༈ྗབ࿷࿗ྱ།༃཯ཉ༬࿧ེ཈ེ࿞གྷཹ༈࿟྿ཙཌྷཡྲྉ༸࿟࿧༾ཋ࿿࿲࿏ཛྷ༇࿌࿧༪ྰའ༇མཆྴ࿭࿡྄࿶༗ཐ༞࿕࿸࿕࿲࿼ྺཕ࿶྄༠ྯ༕࿮ཡཎ྽ཛཆྕ཈ཷྠ༭༶ཷ࿖༃࿪ག྘࿫ྭ༟྿཈࿵པ༨ྡྷ࿒༰ྰྍ࿰࿅ཅྂ྘་࿧།࿿༌࿼࿯ྡ࿺ཹ༑ྚའ࿗རཱྀྀ྆ྊ༸པ༹ཕཛྷ࿘ྜྷ༝࿡ཡ࿝དྷ༻࿩༲ཬ༦༲པ࿕ཆྊཱཛྶཋཀྵ࿎རྈྷ྿࿅ཉ༃༐ཎཇ࿙࿗ཧཟཨྵཱི༳༵ྕ༠ཚ࿓ྟ࿵ྰྐྵཧ༆གྷ༗ོ࿨༷ྛ࿖࿮ྷཋ༐࿠༎࿃༝ཧ࿚ྻ༛ལ༳ཛྷ།ྐྵྶྣ࿕ཁ࿺བྷ༛ྦྷ࿑་࿱࿛ྈ࿸྿࿝࿼࿽༂࿎࿲༩ཋྰཇ༡ཎ༩ྔ࿞༯༗ྱྯྜྷ༯ྯཹྰྩཛ࿦࿎࿛༬࿳ྠ࿅ྵཌ༬࿶དྨེ༑ཕྙཽ࿖༕ུ࿶༠ྶ࿾ྜྷ༰༟࿂༃࿉ྎྺ࿎࿛༬࿳཈ྫྷཔ༃࿅࿟࿘༇ཋ༳ྼཡཛྷ࿆༚ྕཝམ࿤༉༭ཾ༴ཹ࿻࿢༪ྊྡྷ࿚༟྿༤࿵༱༦༐༧࿟༿࿴࿄࿮༎ཾ࿐་࿠ཬ࿦࿍ཻ࿺༫ྠ༢࿡ྭ༲༚ྐ࿱࿼࿊྆࿮ྷ༃༡ཊ༺࿃࿀ྨ྄༘ྥ༭࿗ྕྕཥ࿈࿫ྐ༫ྠཱཿ࿔༲ཹ༈ྐཀྵ࿱࿾༸࿺ཋ࿅ྕ༺࿃࿽ྉཇྼ༯ཞ࿻༽ཇ࿫ྱ༇཮ྻྴ༢ཥཀ࿶་༼ྐྺ༵ཛྷ༸༱࿩༡ཛྷ༮ྟྒྷྒདྷཕཎ༇ཏ࿜།ླ࿒࿺཈བཌ࿷ཬཇ࿑࿗ྀ࿎༷ྷལཡཔ༹ཡྕ࿵྽ྮྈ࿯࿪ྥ࿆࿗༪࿑ྐྵ࿈࿾࿕ཎྴ༣ྃཕ࿑࿌࿋࿛༻ལཌྷདྷ࿓ྉ༐࿒྾ྶ࿪࿰࿏ྦྷཛྷྊཹྕ࿑࿴࿶༇࿯࿧པཧ༿ོ༪བྷ༨༦༟༤༤࿲པཥཕ༧࿢཮ཻྉ࿨༡༥ྊྒྷའགྷཌྷ༬༜༭༰ྯ༢༠ཀགྔཐ༽༤࿩࿄ྭྷ༒࿅ཫ࿘ཱི࿽࿡ྦྷ༺ྏཱྪུ࿶ཥ࿬ྴམཆ࿼༕ཥ༺དྐ࿄༈ྈༀ཰࿲ཞྉཕ༰༺༙྇ྒ࿏ཇྜ࿷࿻࿛༷ཡྱ࿾ཙ༶྘࿗ྐྵྍ࿒࿌࿋༎༉༤࿳࿎ྵ༃࿵࿶࿁࿿࿻࿄࿮༺༶༩࿌ཆ༥༠࿒ཻ཭གྠྔ࿻༈༊࿗ྐ࿹࿳ཪྴཁ࿞ཤླྀཫ༽ྜྷེ࿴࿟࿵ཆ࿌༠ུ࿶ྰག༇༅࿧པ༗ཥ༺࿋༻ྖ༈༤࿕཰࿨ཉ྅༸࿎ིཷཋ࿿࿏ྪབ࿆ྔ༰།࿦࿬༷ཿྺ࿙࿴ྰ༆࿬ེཐ࿞࿙྿༓དྷ༱ཱྀ࿲ཛྷ྄༿ཽཻ࿮࿲༯ྤཱ྾༪࿿ྶྵ༬࿍ྜྷ࿴༥࿿༆࿎ྛ࿭༱པཔམ༯༷ྎ཭༚྽ཐ࿰࿙༝࿟྾ཡ྽࿤ཱུྱ༼࿉࿦ྡྦྷྭ࿢ༀ༑༱࿰༺ནྶེལ࿔ླྀ༦࿗࿡࿏༘࿄ྙྦ༅཯༩ཕྭ༉ཁྦ࿷ྠྌ࿱ཌྜྷྪ࿡࿱࿉࿓࿹ྎ࿘࿥ཱ࿾༆༄ཋཫཻྏྴ༶༞འ༇ཤྔྏྐྵྯྕ༐࿰༡࿑࿣࿴༥༁༌༄࿚༜༢࿯༣ྕ࿬རྀ࿥༸ྥཱུ༽࿛བྷྚྟ༉࿠ྞྭ࿎མ༠཰ྫྷརཿ༟༽࿣྽࿧༆༢࿶࿥࿆࿬༈༶༖ྤྕ༠ཌྷ࿶ཎ༅ཻཚ࿺ྡྃྗ࿞༝࿘཭༗ག༫ྲྚྷཫ࿫࿘࿖༄ྡྷཧྮྗ࿦ྱ࿆ཞཷོ༰ྟ༭༿།࿐ོྐྜྷླ༮༈࿎࿍ཀྵ࿫༧ླྀ༂གད࿵ཇ࿙࿽࿄ྴ྇࿨༲༃ཀ࿮ཎ༔ྵ཰༿ཧཪཱི༣༑ཏ༔ཪ༭༸ྲྀཐྂྣ࿽འྛ༚࿮࿸༱ྒྷ࿢࿐བྷཹྠༀ༽ཪ་࿘༛ྒྕྒ࿎ྨཽཋས་ཆ࿽࿔࿤࿳ྶཷྐ༚༏ཽ࿈༳ྛྊྩ཮༰ག࿍཯࿴ཁ࿿ྍ࿎ྛ࿭༱པཔྨ༯ༀྎཷ༚྽ླ࿰ྈ༝ཛ྾ཡ྽࿤ྚྱ༂࿉ྪྡྦྷྭ࿢ྂ༑ྴ࿰࿦ནྶེལྪླྀ࿦࿗࿱࿏༘࿄ྙ༬༅࿉༩ྼྭཌྷཎྦྌྠ༌࿱ཚྜྷྪ࿡࿱཭࿓࿝ྎ༙࿥༚࿾༆࿺ཋཎཻཾྴ༶༞འཙཤ࿗ྏཀྯྕ༐࿰དྷ࿑࿤࿴ཝ༁གྷ༄࿚༁༢཈༣࿧࿬རྀ࿥༸ྥཱུ༽༎བྷྚྟ༉࿣ྞཀ࿎ྨ༠཰ྫྷརད༟࿵࿣ྂ࿧࿪༢࿶༼࿆ན༈ྡ༖ྤྕ༠གྷ࿶࿠༅࿫ཚ࿷༶༙ྃ࿞ྸ࿘࿋ཪག༫ྲྲྀྷ༵࿫࿎࿖༄ྡྷཧདྗ༑ྱྖིཷོ༰༅༭༳།࿷ོ༦྇༑࿎༼བྷ༇པྀྷ࿨ླྀང࿋࿆࿀༗༶࿤གྷ༅༕ཆཊྒ࿬཭ྟ༪ཌ࿷ྙཇ࿑་࿱࿛༤ལ཰࿝༱ཱྀཕཛྷ࿛ྦཪ࿜࿱ྗབྤ༚ཝཬྰ࿈ྴ࿙ྜ༇ཤ࿡༼༪བྷད༸༟ཙ༉࿨༴ཥྦྷཬ࿞ཱི༖༑࿝ྚ࿅༤࿩༲ཬ࿡࿉ྣྈབ༟ཤཛ࿬ཥཀྵ࿎࿹཰ྷྠཡ࿓༃࿅ཎ࿵མྎ༗ྂཊ࿙༅࿖࿜༧ྐྵ࿉༇༬།༇ཹྰྭ࿶࿰྄࿟࿼ྋ࿻ྭྷ࿩࿘࿠࿎ལྒྷཱྀ࿨༡།྇࿻༮༽༗ྱ࿼࿃ཾ༱༢࿦ྩྭ࿦࿎༎༬ྷༀྫྷ༱ྠ༳༌ད࿙࿗࿦࿅ཕ༥྇ྰ༽༥༢ྱྣ࿃༪ྴ࿌ྃྭ༊ྊླྀ࿚༟ྠ࿕ཇཞ࿩ྼ༧ྖ྽ྮམྼ࿪ྥ࿾࿰༰༥࿡༲པཙཾ༟࿷།ཕ࿑༚ྍྖ࿳࿕༓࿅࿓ྛཅ࿒༪འཿ࿰࿟࿲ཛྷ྆࿭༵༾ྰང༟྽࿵ཛྷ࿚ཧྚ࿒༗ད࿨ༀ྿༻ྡྷཔ༦࿵ཫ࿎ལ༝ཧཋྗ࿡ྱབྷཞཷོ༰࿜༭ཿ།࿷ོ࿴ྜྷླ࿩༈࿹࿍྅࿫༧ླྀ༂࿉དྪཇཌྷ࿽ཧ࿺྇༼༲༨ཀོཎ༔ྵ཰࿪ཧ࿓ཱིྣ༑࿀༔ཪ࿓༸དཐཁྣ༢འྛྒྷ࿮ཙ༱࿀࿢࿼࿐ཹ྘ༀཕཪྸ࿘༛ྒྕ༒࿎༉ཽྛས࿌࿧࿽࿂࿤ཱིྶཉྐ࿖༏ཽཎ༳ྰྊ཈཮༰ག࿍ྱ࿴ཛྷ࿿ྐ࿎ྛ࿭༱ཬཔ༉༯༷ྎྯ༚྽ྉ࿰࿯༝དྷ྾࿨྽࿤ྚྱ࿱࿉ྪྡྦྷྭ࿢ྂ༑ྴ࿰ཥནྶེལ࿢ླྀྺ࿗༳࿏༘࿄ྙག༅ན༩ྖྭ༉ཁྦ༄ྠ࿣࿱༲ྜྷཅ࿡࿱༩࿓༐ྎ༟ྶཱ࿾༆ྏཋཻྂཨྴ༶༞འུཤ༖ྏ༠ྯྕ༐࿰ྼ࿑ྥ࿴ཝ༁གྷ༄༸༬ེ༸࿤དཆཋཀྵ࿮ྚ࿝ྦྷ࿔༲࿑༃࿬༴༅༰ཷ༕ྒ༛࿈ཛ࿋ྫྷ༤྿༤ཅྲ༃ཕ࿠࿟ཙ࿩ྨ༙ྍྥ྘༕࿠ཛྷ࿴ང༴ཙཱེིུྼ࿞࿈ཧྭ༽ྠ࿳ཌྷདྷ࿼ཀྵ࿏༰༮ལ༝࿦࿥༛࿝༱࿩༲ཬ༑༲ྴ࿙ཁ࿓࿭ཌྷཐཆ༑࿱ར྿༅࿳࿎ཞྉ༸རྫྷཷཋ༳࿅࿅ཱ࿆ྂ༰༪༑ྩ༉ྦཇྡྷ༦ཧོའཤ༸ྼༀྠཌྷ༥ཌྷཤླྀཎཇྜྷ࿗࿡ྼ༎།་ྺུ࿶༠ྑྯམ།ྊ࿰༑࿬࿡ླ࿎༎༤ྷ༉࿚ལ྿ཞ࿶ད࿙ེ࿴࿟ཾ༚྇༳࿠།ྃའ࿫ྊ࿍ྠཱ༑༆࿶ྊ࿢࿱༟༬࿕࿅ཞེ༥࿵࿔࿆ྎཿྼཇཊ༇࿻࿞ྡྷ༗ྱྲ༬ྜ༟࿰࿡࿢ྕྊཏྭ༟ྠལཡ༇ཀྵ࿅࿹༦༩ཋ࿡ྼྦྷ༥ྦ࿰࿛ྷ༗ྱ࿾༅ཾྴྔ࿦༲ྭ༃࿎࿞ྈཪ࿺༶༩࿹ླྀ྾ཇ࿙࿂༿࿨ཅཆ༭࿂࿧༵ྒ༲༇མ࿵྘࿚ཧྚ࿒ེཀ༞཰ྠྷྡྷ྽༨ྼཬ࿎࿸ཻམ࿹ཿྥྊ༕ཛྷཫ༳ངྲ༅࿧࿼ཹ༃࿁ངྔྀྐཱྀ༻ྊ༸࿼༨࿏྾࿘མ༖༑࿲࿏༄་༞ྫ࿶ླ཯࿺ྜྷཎ༟ཱ࿴༈࿒࿴࿈ཻཊ࿓ྠ࿝཭ཋ࿲࿠༽྇༖ྐྵཡྡྷྡ࿐༕ཆགྷ༜ྗ࿯༭ྡ྘ཛྒ࿋གྷཹ࿔༞࿳ༀ༻ྡྷྯ࿽༸ྖྮ༇ཋཿདྷ࿲ཾྤ࿭྾࿜࿯༇࿙༭ྂ༱࿭࿻ྚྩ࿫༆༧༧ྵཔྫྷཪཀྵ༡༰࿢ྦྵ࿲ྭྗཁ༭࿗ྕ༧࿡཯ྯ༅ཨ༴࿖ཛའ༳ྺ࿎࿛ༀ࿳཰ྫྷྲྛ࿲࿶࿁࿿࿑࿄࿮ཡ༯྆་ྱ།༦࿈࿫༘གྠ࿗ྐྵ࿔࿈ཹ࿱࿨༉ཪྯ༸࿁ཐྏྣ࿽འྛྦྷ࿮ཙ༱༚࿢༱བྷཹྠༀ࿏ཪྒྷ࿘༛ྒྕྒ࿎ཽ༷ཋསྔཆ࿽ཱ࿤༬ྶཷྐ༚༏ཽ྿༳ཋྊྠ཮༰ག࿍ྜྷ࿴༥࿿༆࿎ྛ࿭༱ཁཔམ༯཰ྎ࿓࿖྽ྖ࿰ྨ༝ྪ྾ཡ྽࿤་ྱྐ࿉ྦྷྡཕྭ࿢཰༑ྴ࿰ྺནྩེལྔླཱྀྀ࿗࿿࿏༘࿄ྙ༊༅ྞ༩རྭ༉ཁྦྠྠ༄࿱༲ྜྷཇ༑࿱࿉࿓࿎ྎ࿎࿥ཱ࿾༆བྷཋཎཻཆྴ།༞འཷཤ༙ྏ༿ྯྕ༐࿰࿝࿑ྥ࿴ཌ༁གྷ༄࿚ྠ༢཈༣ྕ࿬རྀ࿥ཱྀྥཱུ༽࿞བྷྙ཮༉ཽྞོ࿎ྜྷ༠཰ྫྷརད༟༺࿣ྏ࿧࿔༢࿶࿽࿆༲༈ྡ༖࿆ྕ༠ཽ࿶།༅࿽ཚྣ༶ྃྒྷ࿞ྸ࿘࿤༗ག༫ྲ࿩ྷཝ࿫࿎࿖༔࿏ཧ࿂ྗ༃ྱ༥ཞཷོ༰࿳༭༳།ྣོ༨྇ླྛ༈࿟࿍྅࿫༧ླྀ༂ྞདཕཇ཈࿽༕࿺྇༃༲༦ཀ࿁ཎ༔ྵ཰ྦྷཧཷཱིྣ༑ྸ༔ཪྦ༸࿁ཐ༶ྣ࿽འྛྔ࿮ཙ༱༚࿢࿼࿐ཹ༣ༀ࿵ཪ࿽࿘ྍ༠ྕཅ࿎༤ཽྉས་ཆ࿽ྗ࿤༬ྶ࿓ྐ࿂༏ཽ༶༳ཋྊ༜཮༰ག࿍ཙ࿴༥࿿ཋ࿎ྛ࿭༱༴པ࿯༯༷ྎྯ༚྽࿡࿰ྨ༝ཡ྾࿅ཞ࿤་ྱྀ࿉ཅྡཕྭ࿢཰༑࿺࿰ྺནྶེལྔླཱྀྀ࿗༹࿏༘࿄ྙ༊༅ྫ༩ྖྭ༉ཁྦྣྠས࿱༲ྜྷྪ࿡࿱༩࿓༐ྎཏ࿥ཱ࿾༆࿠ཋཁཻཊྴ༶༞འ཯ཤ༖ྏ༿ྯྕ༐࿰ྖ࿑ྥ࿴ཛྷ༁གྷ༄࿚཰༢཈༣ྕ࿬རྀ࿥ླྀྥྗ༽༎བྷ༛ྟ༉༧ྞ࿱࿎༻༠཰ྫྷརྙ༟࿛࿣ཁ࿧༆༢࿶ྐྵ࿆༲༈ྡ༖ྤྕ༠ྑ࿶༥༅༢ཚ࿾༶ྃ་࿞ྸ࿘࿤༗ག༫ྲ࿋ྷཝ࿫ྫྷ࿖࿣ྡྷ࿰࿮༛༄༅༳࿸࿶࿚ྱ༷ྰ༊࿙࿴࿻྄࿬࿗࿋࿎༤ྠ཈ཕཪྺྼཬ༆ྦཷ༇ྀྗྡ࿓ྔཬ༧༠཯࿼༳ཀ࿯࿴࿴࿪࿬༕ྐ࿹ྈ࿕ྺཚ༻༢࿵ཎ༎ྟ࿗ྃ࿥༛ཡཁ࿩༲ྱྒྩ༴ྜྷཁ࿼ཧ࿯ྉཆ༑ྀ࿘྿༤ཌྷཡཞ༨༸ྫྷ༜ཷཋ࿿࿵ཅཛྷ྽࿂྾ཬ࿿཯༷ཿ࿴࿈࿴࿻࿁འེྀ༮࿙༓༻࿨༱༒༡༰༎࿙༙ྉ༡༺༄་࿠ྫ࿶࿻ྩཔཱིཾྲ࿌༿ྭ࿶࿴ྑཷྏ࿓࿕ྪ༇༹࿅ཬ࿛࿯ིྃྦྷ࿅ྡ࿾࿖༵ཊ࿴༲཭ྨྂྵྎ࿴ྚའ࿫࿘ཫ༯ྵཔཕ༇ཋ࿏࿑ཇྦཉ࿞༈ྗཎ༩་࿧ྱ༑࿉༟ྟྂཌ࿷ྡྷྡྷ࿑ེྀ࿨࿳༤཰དྷ༴ྺ࿵༾࿛཮࿽༗༶࿸གྷ༅༚࿑ཫྒ࿬ཉྟབ཰ྃམཉཆ༑࿔༎཰࿕཈ཇཞ༹༶༧࿇࿆༝ཱྀདྷ࿏༥࿾࿂྾ར༥ྻༀམཾ࿼༕ཥ༆ྩཹ༌ར༱࿓༓༡ྵ༃༂࿶྾༏༹࿰࿅ཇཎཱ࿆༾ྫྷཀ࿑ༀ࿕༯༴࿭࿦ྀ࿋ྫྷྖ༈࿙༬཈དྷ྽ཋྂ༣࿔࿆༙ྉ࿲ྼཁ༭࿻࿢ོིྱཉཱིྜ༇༢༦ཀག་ྀ࿛࿙ༀ༓ླྀ࿀མ༼࿤ྖཱིཏ༃࿟༺ཾ྽࿰࿧࿜ྒ࿉࿾ྦ༊࿄ྊེ࿞࿶༚ྭ༐༉྿༷ཕ࿼༦།ར࿇࿆࿀ྃ࿝࿲ཁ༭ྒྷྕ࿤ཛྍགྷ࿓ྞ࿓༢࿻དགྷ་࿱࿹ཌལ཰ཅ྽ཀྵ༥༉ཱུ࿆࿂࿦༡ཡཾ࿓ཹྱྱྰྩྣཱིྂ཰༑ྨཙྱ༑ད࿘༷ྠ཰ཅ༝ྥཟ࿤ྫྷ࿯ྒྷྐྵདྷ࿏དྷ࿸༿༲༾࿻࿒ྴམཁ཰࿩ཧཷཱིྣ༑࿀༔ཪཉ༸࿁ཐྏྣེ࿬ྛྙ࿮཮༱ཧ࿢࿼࿐ཹཛྷༀ࿵ཪཻ࿘ྗྒྕྪ࿎ཽ༷࿩ས་ཆ࿽࿪࿤༬ྶ࿆ྐ࿖༏ཽ༜༳ཋྊ༜཮༰ག࿍ྞ࿴༥࿿༆࿎ཋ༗༱༶པཌྷ༯༷ྎྯ༚྽ྉ࿰ྈ༝ྼ྾࿅྽࿤༚ྱྐ࿉ྪྡྦྷྭ࿢ཬ༑ྴ࿰ྺནཚ࿫ལྒྷླྀ྅࿗༳࿏༘࿄ྙྟ༅༊༩ྖྭ࿯ཎྦྌྠ༄࿱གྜྷཕ࿡࿱༩࿓༐ྎ࿂࿥ཱ࿾༆༣ཋཎཻཨྴ༶༞འྜྷཤ༙ྏ༿ྯ༪࿘࿰༨࿑ས࿴྾༁གྷ༄࿚༤༢཈༣༾࿬ྖྀ࿥༕ྥཱུ༽࿞བྷྚྟ༉ྲྞཀ࿎཰༠཰ྫྷར࿻༟༺࿣ཎ࿧༆༢࿶༑࿆༲༈ྡ༖ཪ྾༠ྥ࿶༶༅ེཚྣ༶ྃ࿌࿞ྸ࿘࿒༗ཚ༫ྲྛྷཝ࿫࿎࿖࿣ྡྷཧ࿊ྗ༑ྱྤཞ༩ྭ༰཮༭ྰ།࿷ོ༦྇ླ༝༈࿹࿍ཱྀ࿫ཁ࿥༂࿉དཕཇ཈࿽ཛ࿺྇ྺ༲༦ཀ྄ཎ༔ྵྠ࿴ཤ༎࿑༑དྷ༈༱࿓ྲ࿚࿀ེཟ࿤ཇ࿯࿂༑ཕྦྷཡ༅༿༲༾༳ྶ࿺ཱིྂྎ༶࿭࿞༲ཤྐར࿳༅ཀྵ࿥༻༢࿵ཛྷ࿘཈࿽༑ཟབད༬༳࿑࿠ྃྶྴམ༰ྲྔ༃ྀའ࿭࿱ྐཱྀ࿒࿐༸པྛ࿅࿠༮ྜྷ༢࿡ཟྻ྾ལ༳༧།࿻འཉ཮ཨ࿓ྃཛ࿉ེ࿦࿎࿞ལ༓྿དྷ༱༷ཇ༌དལ༢࿡ྖ༺ཊ༚ཧྶ࿶ཥྩ࿺མྂྲ༑༜࿙ྻ༑ཀ༞༉ཌ཰༡྽ྺྦྷཁ࿢ྜྷྒྷྒ࿥༛༡ཡ༒༲ྱ༦࿬ྴ༅༯྘࿂ྰོ࿋༯༡༈༻ྷ༤࿝྽ཱྀཕཁ྄ཿ࿮ཻ࿮ཡབ྆ྒྷ࿑༪࿡཯ྴཱིུ༢཭࿄࿞࿈་ྭ༮ྠྠཌྷྼ࿼ྋ࿵ཛྷ྄༠༱༡࿮࿅༥ྦྔཆ༾࿿༲཭མ༶༴ཛཿདྶླ༮༈࿟࿍྅࿫༧ླྀ༂༅དཕཇམ࿽༗ྴ྇ྐྵ༲༦ཀདཎ༁ྵ཰ཋཧཷཱི࿾༑࿀༔࿓ྴཐ྇༢ླྀཚད༉ཋ࿭࿥ྗ༶࿆࿖࿑གྷ཈ྈ࿙༭ཎྲ࿂࿡༆༊༗ྭྀྲ࿓༉࿚ལ༉ལ༌དྟྸ༑࿏ཇཛྷྔ࿒ྶ࿶༳࿍པཙཾྊ྘ྋ༮࿑࿌ོ༽࿳༤ྷཎ༂࿫ླྀ྾ཇ྽ྮ࿙ྟཋྥ࿾࿖༰࿑༦༌ྲྜྷ༯ྴཱ༠༆ྶཤྍ࿟࿕༻཰ྫྷཷ༨༡ཊཇ༠࿫࿎࿮࿝བ༇༚༵༥༳༲༇མ༯࿼ཛྃ࿔ྶཹ༈༽࿳྿ལ༡྽࿽༸࿟ཐ༩ཋ࿿ྦྷྼ࿆ྂ࿗༞ྞ༗ྱྣ࿃ཾ࿺࿭࿦འ༥ླ࿎ྼལ࿕྿࿚ལ༉ཞ࿶དཙ࿽࿴࿨ྜ༚྇༳࿠࿠༑ྶེ࿐࿍ྠྔ࿻ོ࿒ྣ࿕࿱༟ༀ཰༡྽ེ།࿵ྚ࿆ྒྷྃ࿲࿏ཛྷ༩ྒྷ࿧།༦࿶཭ྦུ࿽ད࿭࿞࿶་ོྼ༷࿕ྺ༪༻༢དྷ࿑࿛ཙ༙ྰཎཫ༔༅༚ཛྷཫ࿻࿉ྣཞུྠ࿎࿡༆ྕླ࿶ཡ࿺࿓༻ྫྷཔཥ༡ཛྷ༰࿸༹࿰࿟༡ཛྷ྆࿭ྕརཝ࿑ༀྈ།࿺࿭ླ࿁࿪གྷ༐༈ༀༀ࿺༶ྵཤླྀྕ༺ཙཻ࿦࿵ྦྷ༯཮ྤཞ࿣ཤྩ࿼཈།ྯ࿗ྃ࿋ྶ࿌༐ྀ༟༻༉࿚ལྠ༨༌དལ࿽࿡ཇ࿝ཁཱ཭ྶ࿶༳ྶཔ࿙ྻཪ྘ྫྷ༮࿑ེ༸༐࿕ཙལ།༊࿫ླྀ༪࿟྽ྮྨླྍྥ༇࿗ཬྱླ༲ཉ༬ྡྷ࿶༦ཧ྄ཚ࿫྄࿘྿༬ༀླྀ࿀ྖྐ࿤ར࿯࿽ླཇྼཾྣཛ࿧ཊ༠྾࿽࿁གྠ࿗ྰ࿔༊࿰ྭ࿨༤ཷཀྵླྀྟ༢࿨ྕ࿢མ༖༳༡༺ྏ༇་ཬཬ༠ྕ༤༭༯༉ྃཧ༆ྜྷཤ༈࿱࿼༹྇࿱ྷྋཕ༰ྫྷྨ༙ླ࿨༯༒ལ༳ཛྷ࿠ྃང࿾མྂ༱ྊ༒ྦྷ࿑࿖ོ࿛༻࿸༻དྷ࿼ེྡྕ༆ཻ࿆༿࿟༡༄࿌ྺཉ࿶༠࿶༇ྟྜཷྔ࿦༼ྩྔྍྫྷྠ྿཈࿲཭ཥ࿅࿠࿵ཙྸྰ࿨ཡ༥࿓ཛཬ࿜༕྄࿃ྕྞ༟࿭ྰཀྩཹྐ༮཰ༀ྿ྼ࿓༒࿅ཝ࿎༅࿀༑࿏࿲༯࿾࿻༽འ࿽ྱ࿓࿕ྡ༟࿗༑ྍ࿉༗༈࿘࿸ཷ༨࿜༻༢࿵ཛྷ࿛ྟ༝ྉ࿥ྙདྷ༔࿩༲ྱ༦࿒࿺཈ཨཔཤྨཻཆ༑྄࿹཰࿳ཌཡྵ༹༥༓࿇ི࿆ཿཇ࿏བ྆ཛྱར࿏༰ༀྈཎྴ࿂࿰࿢࿁࿽ྖ༈ྠ༓ༀཕཉཥ༶༥࿔࿆࿂ྉདྷྡྷ༶࿆༭ྒངཤང༇྇ཎ༟࿗༜࿇ྱ༑࿔རལྷ༉࿅༬࿫ླྀཫ࿛ྦཉ༈༨ྗྜ࿓ཏཬྕ࿴༌ྯ࿙ཨྵ࿰࿴༆༊་࿔ྼལ༤࿳ཡཪཋ༸ྫྷ༲ཷཋྒ࿨࿏༥ཞ༕༾࿠࿿࿬཰ཞྞྊཤཛྩཱུཥ࿎࿛ཌྷ༉ྫྷ྽ྛྡྷ༰࿞྽࿩࿙࿡༘ྥ࿓࿭༰ཫ༃ག࿽࿿༫ྠཛ༃࿋ུ࿰༆ཬ༨ྵཔ༡ྲ྅ྡྷཛྷ࿵྆ྮ࿰࿅ྪ༄༚༿ྫ࿶༦འྴམ།ྵ࿭࿦ྚ࿤ླ࿘༵༊ྵཔ࿅༇྅ཕཎ࿞༠࿅༕࿮ཇྏ༩ྒྷཆ༧ཌྷམ༉༭༶ཷྔྃ༺༆ཅདྷ༈࿸ༀ༉࿎࿺྅࿲༵༮༅ྛ༗ྏ༤གྷ༅ཛཆཊ࿦࿉༇࿙ྻ࿄༲ྎ࿞࿈ྔོ࿟཰ༀ཰ྫྷཏ༳ཟ࿤༺࿙༖ྃྼ࿲༄་࿽ུ࿶ླ༌࿼཮ཾ࿼ྔླ࿢༪྘ྍ࿮༟༅ལཡ࿺྅ྼ࿑࿟ྨྎ༜࿵࿪ྥ༭࿂༵࿑࿿ག༱ཙཁ༴ྊ༿ཕ࿑༚ྭ༎༬༓༤࿨཭ྺ࿘࿶྄༿ྐྵཻ࿮ཇ།ྦ་༰ཊ࿡འྣ༬ྡྷཅ༨ཧ༼࿶࿭࿔࿨ༀཌ༻ྪ࿺༉࿓༁དཙ༏࿴࿝ཇཨ࿓ྒྷགར་ྻༀ࿕ཁ༟ཱ༠༆࿶ཹར࿱ྺ༃ྲ༸཭ྋཡཬ࿑ཊྛ࿰ྪྦྷཆ࿆ྤ࿅࿤ཤང࿺ྜྷ༶ེ༆࿰࿞ངཛ࿔༎༱ཷ྅ྒ྇༢࿅༧༎ྨྒྷ༿࿨࿵༡ཧ࿩༲༪࿻༲༇༬ྂ༇ཹ༜ྎྱ༑࿋ར࿸྿༉࿵࿕༉རྌདྈ༝ྒ࿅ཅཁ༩ཱཆཛྷ༕༆ྴཾྞཷ࿭࿦༛ཚ࿫༈࿘༉࿸཈࿅࿼༃ཅ༧྄ྒྸེ࿮࿅ཎ࿷࿰༰࿠ྃྶྴ཈༰࿓༢༃࿢༪ྣྏ༦༟཰ཌྷདྷཉ྅࿏ཁ࿞࿸༙࿿࿨ཡབ྆࿂࿞࿾࿨ྱྵ྇ྡྴ༕ྰ྄འེ༆ྖ࿸཰྿࿎྽༉࿄༄ད࿃༢༑࿝༺༯྘࿭࿑࿠༑༲༉྽ྪྉ༦ཧ༈࿤ཛཐ࿘྿༬༤༥྾ཤླྀྕ࿵ྨ࿂࿦དྷཅ།ྔཅུ࿶ླ࿬ྴྈ༪ྵ༢࿴༺࿪ྀྎ༈ྈ༬཈ཅྲཀྵ࿝༪࿛࿯ེྐྵ࿅࿲ཛྷྦཤཛྷ༾ཥ྾ེ༯྇ྠཛྐྵ࿁࿤࿗ྀ࿞༬ལ༻࿲ྵཥྦྷཁ༽ྨེཿྖྚ࿝ྷཱུ༲ཬ༠࿬࿾࿃།༱༗ྐྵ࿔ྶ࿌ྀ༮ྈཙ࿺ཁ༻ཤླྀ྾࿛ྨ༖ྃྪཅཾ཮༩࿷ྌཤང༇༅༰࿓࿰ྰ྄ུ࿌྄࿨ཌཌ࿺༥ྡཹླྀཛྷ࿎ྜྷ࿀ླ࿝ཅ༯༩࿖ྱ༥༕ྍ࿊ཉྞྵཱ࿴༼ྩ࿭༆༮࿙༅༓དྷ࿕ྠ༺༁དྈཏླཇྪྏྊཹཚ࿤ཤྶཎྟ࿧ཌ྘ཚཕ࿑༕ྭ࿎༷༬ྠ࿎ྲ༃ཕ࿶྄༠༨ཻ࿮ཡ།ཞ࿖ཆ༧༠ཚ཭ྟཇ༮༨ཧོ࿉ཧ྄༐࿳ཌ༤ྪྯཌ༩༌དྨ༢༑࿏༺བ཮྽ྈ྿ཤ࿍࿼ྟ༯༱༢ྃ࿋ྶ࿰ཐ࿨࿳࿸ཌྷ࿨ྲ༦ཅ࿑྄༳༴ཻ࿮ཡ༯ྦ࿌ྕ࿠࿦ྑྵ࿯ུ༢྽༡࿞༲༗ྐ༞ྈ࿳ལཡ༱࿴࿵༪࿢ྈྒྷླ࿝࿏ཊ༩࿻༮༑༢ྱྲ྇ཆ༇࿭ྃཀག࿴࿶ྖྣ࿓ལཅཉཀྵ༡྾༮࿯࿩ྈགྷྍྥ࿆࿗༪ྱླག཭྇࿍཰ྊ࿐࿢࿑࿖࿱ྖ࿕༹ྎ࿚ྷ࿩ྡྷཝྫྷ࿿࿢ཧ࿮ཇྜ༩༕࿢࿺ཹྱ༇ྨཨ༱༑མ཯ཆ༑࿋࿟༷༓཰ྡྷཞ྅༸རཋྯཋྉཡ࿵།࿐༚༵ྱྰཚ࿼ཱི༯ྴ࿡ཛ࿞ཚ༗༈ྐ༨ྦ࿐༸྽ཀྵ࿵࿑ར࿃ཏཿཟྜྥ༻༳༾༥༑࿍࿾཮ྂ༇༗ྃ༺࿪࿳ྼ༈࿸࿕ༀ༡࿓༹ྼཁར࿃༢༿ཟ༯ཞྷ༳༵ཫ༦࿒཭མ༶ྯ࿂༠࿪ང༃࿘༈ཽ࿳༉ླྀ༙༰࿦࿤ྫྷལྒྷ༑࿲ྼཁ྽ཏ྾ྕྒ࿒ྵ཮༯࿼࿗ཛ࿉།ྺ࿎༞ༀ༅ཌྷྪ࿓ཋཅ࿒྾༣ྙ࿰ཕ࿵ཨ࿾༚ཝཛྷླགཔ࿕ཆ྘࿖࿻ོང࿖࿋༽ༀ཰ྠཡ༇༨࿨࿠༺༅࿩ྨ༩ཋྥ࿾࿂༪ཛྷླ࿶ྵ྇ཁ࿓࿂࿻ྀ༊ཛ༆ྫྷ࿳༬༉࿎࿓༹࿅ཫ༽ྦཉ࿛ྀྗཎ༭ཤ࿠࿑ཥྩྴཞ༊ྠཹྃ࿢ྣ༑ྴ࿰ྒནྶེལ༎ླཱྀྀ࿗ཿ࿏༹࿽ྙྦ༅ྫ༩࿭ྭ༉ཁྦྌྠ༄࿱ཚྜྷཅ࿡࿱ཆ࿓࿘ྎྀ࿥ཱ࿾༆།ཋཁཻ༯ྴ༴࿢འ༇ཤ༖ྏ༸ྯྕ༐࿰༨࿑༄࿴࿜༁གྷ༄࿚༵༢࿙༣ྴ࿬རྀ࿥ཧྥྙ༽རབྷྚྟ༉༣ྞ࿱࿎࿯༠ༀྫྷར༹༟༺࿣྘ཆ࿪༢࿶ླ࿆࿉༈པ༖ྤྕ༠࿣࿶༥༅ེཚྈྡྃྗ࿞ྒྷ࿘ྯ༗ག༫ྲྔྷཛྷ࿫ྛ࿖࿣ྡྷཧ࿂ྗླྱཫཞཷོ༰࿳༭ཿ།ྊོ༨྇ླ࿵༈࿟࿍༼ེཬླྀ༂ཱིདཕཇྶ࿄ཧྴ྇༨༲༦ཀ࿏ཁ༔ྯ཰࿪ཧཉཱིྣ༑࿀༔ཪ࿜༸࿁ཐབྷ࿾࿄འྛ༮࿮༅༱ཻ࿢࿼࿐ཹྴༀཇཪ࿄࿘ྮ༠ྕཅ࿎༤ཽ༃ས་ཆ࿽ྗ࿤࿕ྶ༇ྐ࿂༏ཽ࿈༳ྮྊབ཮༰ག࿍྇࿴ྡ࿿࿔࿎ྙ༗༱࿈པ཈༯༲ྎྯ༚྽ྖ࿰ཌྷ༝ྪ྾ཡ྽࿤ཱུྱྭ࿉ཡྡྦྷྭ࿢ༀ༑ྲ࿰࿞ནྶེལ༏ླྀ྅࿗༠࿏ྙ࿄ྙཱི༅ྫ༩༢ོྠཁྦ཰ྠ࿣࿱࿺ྜྷྪ࿡࿱࿜࿓࿎ྎ༖࿥༞ྣ༆༄ཋྏཻྡྴ༶༞འ༇ཤྒྷྏ࿦ྯྕ༐࿰༨࿑ྌ࿴཭༁གྷ༄࿚༵༢༜༣྽࿬རྀ࿥ླྀྥྚ༽༞བྷཱུྟ༉ྴྞ࿱࿎ྊྒༀྫྷརྰ༟༎࿣༁ཆྮྎ࿶ླ࿆ཚ༈ཆ༖ྤྕ༠ༀ࿶༶༅༢ཚཾྡྃཏ࿞ྒྷ࿘ང༗བནྲདྷ࿠࿫ཏ༚༄ྡྷཧ࿿ྗ࿡ྱཚ྽ྯྭ༰༊༭ྰ།ཫོ༦྇ླྡྷ༈࿹࿍ཱྀ࿫ང࿥༂཭དཅཇ༁࿽༕࿺྇࿨༲ཱྀཀོཎ༔ྵ཰ཕཧྵཱིྤ༑࿀༔ཪ࿓༸དཐ༶ྣིའྛ༞࿮༅༱ྸ༞ྲ࿐ཹ༴ༀཇཪ࿢༐ད༠ྕྮ࿎཰ཽ༚༄་࿧࿽༹࿤࿕ྶ࿜ྀ࿖༏ཽ࿈༳ྮྊ࿕཮༰ག࿍ྩ࿴ྡ࿿࿔࿎ྙ༗༱࿈པ཈༯༅ྎྯ༚྽ྉ࿰ྨ༝࿨྾࿨྽࿤༺ྱ༈࿉ྐྵྡྦྷྭ࿢ྲ༑༱࿰༦ན࿃࿫ལ࿔ླྀ༦࿗༂࿏༘࿄ྙྦ༅཯༩࿞ྭ༉ཁྦ࿷ྠྌ࿱࿶ྜྷྪ࿡࿱࿉࿓࿹ྎ࿱࿥ཱ࿾༆བྷཋྏཻྻྴ།༞འྟཤ༖ྏ༘ྵ༾༐࿰༕࿑༄࿴༬༁གྷ༄࿚࿤༢མ༣༾࿬༕ྐ࿥ཧྥྲྀ༽རབྷྚྟ༉ཽྞ༈࿎཮༠཰ྫྷརཏ༟༞࿣འ࿧༆༢࿶ི࿆ྩ༈࿑༖ྤྕ༠ྑ࿶ྡ༅ཻཚ࿷༶ྃ࿛࿞ྒྷ࿘࿠࿭༲༫ྲདྷཊ࿫࿱༚༜࿏ཧཋྗ࿴ྱ༣ཞཷོ༰ྟ༭࿻།ྣ྄ོྜྷླྡྷ༈ར࿍ྉ࿫༄࿥༂࿸དྦྷཇྫ࿄ཤ࿺྇༑༲༨ཀྔཁ࿙ྯ཰ྍཧ࿓ཱི༧༑࿀༔ཪ྾༸࿋ཐཎྣཱྀ࿬ྛྙ࿮ྜྷ༱ྪ࿢࿼࿐ཹྠༀྦྷཪ༖࿘༛ྒྕཅ࿎ཌཽྺས་ཆ࿽ྗ࿤࿳ྶྯྐ࿂༏ཽ༌༳ྮྊༀྟ࿜ག࿍ན࿴ྡ࿿༦ྫྷྺ༗༱༟པཌྷ༯࿷༢ྯ࿖྽ྭ࿰ྨ༝ཛྕཡ྽࿤༺ྱ༈࿉༃ྡྦྷྭ࿢ྏ༑࿼࿰ྺནྶེལ༏ླྀཀྵ࿗࿻࿏࿇࿄ྙ༻༅ུ༩࿻ྭ༉ཁྦ࿈ྠྥ࿱གྜྷ༽༑࿱༭࿓ྖྎ༝࿥ཱ࿾༆ཝཋཎཻ༯ྴ༶༞འྶཤ༙ྏ༠ྯྕ༐࿰ྫྷ࿑༄࿴ཛྷ༁༌༄࿚཈༢཈༣྾࿬རྀ࿮ྗྥ཮༳༲༷ཤཞༀྦ࿍ྎ༶ྎ࿞ང༚࿱༽ྠ࿕ལ࿎ཏ༌ོ࿤༽ཱི࿂༃༡ཕཊྣ࿆༲༄ཤ࿶༟མཨཔ࿭࿡ཀད༥༐༈༻ལ࿺ཁྡཛླྀ྾ྫྷྨ༏࿦࿵ཅཎཞ࿰ག࿎༩ྤༀ཈བ༴ཱཥ࿔༊༚༆࿛ལ༅࿕࿲཭ྺ࿲ྕ༺ྈ࿂ྐྵ࿵ྪ༥྽༚྾གྷྨ༄࿯༭ཎྲ࿂ཥ࿪༊࿭༸࿘༉ཙༀྫྷཉ࿽༂ྫྷྫྷབཋ༳ཡཡ།྆࿌ྕ࿠࿦འ༴࿯ཨ༱༕ླ༛ུ࿗ྀ࿛༤ྋ༞࿡ྷ༦࿝ཊཇལ࿗ྰ༡࿅ཁ࿆࿖༰།༑༲༱ྟཁྴ࿗ླ࿬࿈ཐ࿎༎ༀ༓ྷ࿵༱༒ྡྷཬཇལ༏ྰ࿵࿲བྊ༕ཝ༵༑࿒ཻདྷྟྠ࿗ྃ࿔གྔ࿋ྖལ༤ལྪྵཥཕཬྫྷམྎ༗ཎ༼༔༅ྒྷ༧༥࿦࿈༟྽ྡྷ༬༦ཧ༛༲ེ࿋༞༉ྠཌླྀྸྪཟ࿤࿟ཱིྎྒ࿨࿲༄༚ོྶ࿶࿦༌ཉྟ།࿓ྃ༕༲ྭཟ࿎༎༤༓ྷྼ࿼ཀྵ࿲ཎ࿞ྈྒྷྒྦྷ࿏ྜཞཤ࿢༽ཡྱཉ཮ྜཪ࿰࿦࿁࿶࿌ྭ࿞༤྿ལྡྷ࿓ཱྀཅ࿒࿑ལ༹࿰༡ཅ༶྘ྒྷྱགྷ཈ྩ཈༭ཁ࿺ཤ༦ོ༊ེ༈༽ྈ࿕༓ླྀ༝བྷླ࿤༞཮༏ྒདྷ༺ཎ࿷ཹ࿧༪༳࿬༟཮࿧ཌ྘ཐྦྷ࿑ཹ༸ྖ༬࿳ྠྼ࿼ེྏ࿨༆ེ࿆༿དྷཡ༄ྔ༘཯࿶ྒ࿍࿓ྈ།࿓ཧྐྵ࿔འ࿭ྀ༐ྠཪབ༸࿁ཐ༰ྣ࿽འྛྡྷ࿮ཙ༱༚࿢༟བྷཹ༉ༀ࿵ཪ࿽࿘ྚྒྕྛ࿎ཽ༷༠ས་ཆ࿽࿊࿤༬ྶ࿾ྐ࿖༏ཽ༶༳ཋྊ༜཮༰ག࿍ཙ࿴༥࿿ད࿎ྛ࿭༱།པམ༯༅ྎྯ༚྽࿡࿰ྈ༝ཡ྾ྼཞ࿤ྚྱྐ࿉ྪྡཅྭ࿢ྂ༑ྴ࿰྅ནྶེལྪླཱྀྀ࿗ྐྵ࿏༘࿄ྙྤ༅ྞ༩རྭ༉ཁྦ࿤ྠ༄࿱ཚྜྷྪ࿡࿱ཆ࿓༐ྎ࿫࿥ཱ࿾༆།ཋཎཻཨྴ༥࿢འཷཤ༙ྏ༿ྯྕ༐࿰࿝࿑ྥ࿴༵༁གྷ༄࿚࿠༢ཌྷ༣ྕ࿬རྀ࿥࿰ྥྚ༽࿞བྷཱུྟ༉ཫྞོ࿎཈ྒྠ࿎རྰ༟࿛࿣༧ཆ࿋ྎ࿶༈࿆࿉༈༥༖࿆ྕ༠༄࿶།༅ེཚྣ༶࿴ཧ༎ྱ༑࿎࿦༟ཆཔླྀཏྎ༼࿤ཇ྇༖༑࿝༡ཎ༩་࿑།ླ༌༴ཞྫྠཧཛ࿬ྠཀྵ࿎࿞ྠལ྿ྫྷ࿓ྋ࿅༪༽མཏ༗༶༐གྷ༅࿌྾༧࿴࿈࿼མཾཌ࿷༯ྡྷ࿑࿖ཐྫྷ༉ྷྠཡ཭࿴࿨༰࿘༅ིཧ࿚ྻགྞ༳࿠༪࿴འཉ཈༯༟ཛ࿻࿋࿉ེཐ༽྿ྮ༭ྃྷ༃࿅ཛྷྖ཈ེ༿࿟ྪཁ࿆࿰༰ཛྷཥྩ༉྽ཇ༞ྐྵཧ༼༲࿭ད࿨࿕࿊྄࿮ྷ༨དྷ࿠ཇ࿃࿽࿯࿆༘ྥ࿾ཤྕྱྐྵཚ༉྽ཇ༫༨ཧྍངཧྐ࿘཰༬཰ཇྲ཰༾ྌདྨི༃དྷ࿵ཨ༭་࿧༥ྨ྘࿙༭ཁྵཱཿ༆ངཤྍ࿱࿼࿩࿧࿱ྷ༃ྦྷཁ࿵མ༝ཿ࿵༯༞ལ༳࿠ྕ༑࿍࿺ཱི༪࿺྘࿳ྦྷ࿑࿗༼ྫྷ༷࿕཰࿎ྯ࿽༂ྫྷཛྷ༇ཋྒ࿲࿏༥྽࿂྾།࿯༴࿙༭ཾཔྔ࿻ྀུཛྍཬྛྤཔ࿲པ྅དྷཁ࿘཈ཏྨཾ༛ྥ࿷࿌འ༌ཌྷཱ཈༭༶༴ཹ࿡྄࿈ཹོྼ࿙ༀ༻༥ཞཛླྀ࿑࿘཈༝ཿྦྷ༡ྜྣཤག࿎༥ྻༀ཈ཨ࿼ྔྐྵ༼࿤ྔ࿘ཬ༔༲པ࿎ཉ࿴དྷཎཇ࿯࿀ྒདྷཕྏ྆ཛ࿧࿜࿿༌ྣྈཁྊཹ༦྄འཹད༞ལ྿ཌྷ࿵࿺ེྏྐ༒࿆ྸ࿡࿝༎ྏ༩࿌ྕ།࿦༌༟࿯ྜ༱ྎྃ࿋࿤ཤརྀ༨བ༣༸ཞ༹ཕཬ༺཮ྒྷ࿴࿲ཅཁ༇ཱཛྷར྿༯ༀམཾཔྎྃ༼ྩེ༸༮࿕༓࿺ཎྒྷཹླྀྕརྟེ༑࿏ཇྂ࿓ཱ༧༥ཛ༰ༀ࿃ྯྴ࿰ཛ༲ཨཀྵ࿎༽༷༻ྷ࿅༱ཥཡ༵རྨིཧ࿚༯༕༻༳ཛྷྕ࿦࿶༱࿯ྻྯ࿌ྃའཋྺ࿎࿞࿸࿳ༀ࿎༇ྛ࿘࿒྾ྑ࿪࿰ཕ࿲ཆ྆࿖༾ཊྐྵཚ࿺ཙ༰༟༕ྒྀྕ༃ྑག࿷࿓༉ཕ࿓ཋཡཝ༎ལ࿽࿡ཁཛགྷ༅ཏཬཫ࿿࿬༟ཱིྜཌ྘༪༒࿑༚༆ྖཌ༬ྠྫྷཔ༹ྦྷྕ࿛ཙཻྐྵ࿨࿏ཆ࿐ཹ༵༥ྰ࿉༴༅ྻཪ༕ྰདྶ࿴࿶༺ྣ࿓ༀ࿝ཪྉ༡༾༮མ࿩࿯࿪ྍྥྊྔ࿠ཊ༃࿬༴༬༊྿࿴༃࿢ྕ࿐ལྭ༟཰ཌྷ࿨࿼྅࿨࿟ྲ༩ཋྒ༡ྡྷ༥༩ཤ༽ྩ༗ྱ࿾ཱིཾཔ࿌ྒ࿬ཬ༃࿎࿨༉ཉྲ༸཭࿥དྷཫ༆྆ཷཅྀྗྜྣྒྷ༵༥༳࿶ྴྰ࿯࿯࿴࿻ྍ࿶༕ཀ༎཰ྠྴླྀྷ༦ྎཬ༆༄ཋཎཻ࿼ྴ༶༞འ༻ཤ༝ྏ༿ྯཞ࿘࿰ྎ࿑ྥ࿴ཝ༁༌ས࿚མ༢ཌྷ༣ྕ࿬རྀ࿥༦ྥྚ༽རབྷྚྟ༉༱ྞོ࿎ྈ༠ྠ࿎ར༳༟࿞࿣ཎ࿧༆༢࿶ི࿆འ༈ཆ